  ["a80415744d66c987"] = { "我々は日の出とともに起きた。Barnilは朝食の支度を始めた。私は、Ajeckの注意がどこかそれていることに気づいた。その日の行程は長く、狩りは我々を危険の近くへと導くはずだった。集中を欠けば、たやすく思わぬ事故につながりかねない。それなのにAjeckは、川べりに立って食器を洗っているBarnilから目を離せないようだった。", "." },
  ["a812cdacf6119792"] = { "一つの旗の下に団結した人間の部族は、力強く楽観的な文化を育んだ。Arathorの王Thoradinは、北の地の謎めいたエルフたちがトロールに絶えず包囲されていることを知っていたが、人里離れたよそ者を守るために自国民の安全を危険にさらすことを拒んだ。エルフが敗北したらしいという噂が北から少しずつ伝わってくるまま、何か月もが過ぎた。Quel'Thalasからの疲れ果てた大使たちがStromに到着して初めて、Thoradinはトロールの脅威が真にどれほど大きいかを悟った。", "." },
  ["a87855bfb17b9c85"] = { "恐ろしい爆発を生き延びたわずかなナイトエルフたちは、粗末ないかだで寄り集まり、視界に入る唯一の陸地へとゆっくり向かった。どういうわけか、Eluneの恩寵によって、Malfurion、Tyrande、CenariusはGreat Sunderingを生き延びていた。疲れ果てた英雄たちは、生き残った仲間を導き、民のための新たな故郷を築くことに同意した。", "." },
  ["a881de3e6a771cdd"] = { "Illidanは同意し、ただちにFrozen Throneを破壊しに向かった。それはLich Kingの魂が宿る氷の水晶の棺である。IllidanはFrozen Throneを破壊するには強大な遺物が必要だと知っていた。Gul'danの記憶から得た知識を用い、IllidanはTomb of Sargerasを探し出し、Dark Titanの遺骸を手に入れることにした。", "." },
  ["a88dbe9ad9c283f6"] = { "ほどなくして、霊性を重んじていたその種族は、血に飢えた民へと変貌した。Kil'jaedenはさらに、Ner'zhulとその民に最後の一歩を踏み出すよう促した。死と戦争の追求に完全に身を委ねよ、と。しかし老シャーマンは、自らの民が永遠に憎しみの奴隷となることを察し、どうにか悪魔の命令に抗った。", "." },
  ["a8aa2a9489f9a5dd"] = { "Valikへ\n我々が戻るまで奴隷を見張っておけ。ソレをこれ以上ここに置いておくのは危険だ。人目につく恐れのない、もっと北へ移すつもりだ。\n\n奴らは獣だが、それでも獰猛な獣だ――数が揃えば、警戒するだけの理由がある。奴らを刺激しかねない痕跡は、一切隠しておくに越したことはない。奴らに結集して総力で我々を襲う理由を与えることだけは、何としても避けたい。", "." },
  ["a8b0b486a9785c7a"] = { "Magniの髭にかけて、話すことは山ほどあるのに時間がほとんどねえ、{name}。できるだけ早く、Coldridge Valleyを見下ろすAnvilmarまで俺を訪ねてこい。さっそく始めなきゃならねえ。\n\nお前に教えて追いつかせてやれることは山ほどあるが、そいつは今のところ俺たちには関係ねえ……今のところはな。俺たちが集中すべきは、斧の握り、鎧の重さ、そして敵と戦いながら額を伝う自分の汗の匂いだ。まずはそこから始めるぞ。\n\n-ウォリアーのトレーナー、Thran Khorman", "." },
  ["a8d6c46ef5e70d10"] = { "Sargerasの狂気がその勇敢な精神の最後の名残まで呑み尽くしたころには、彼は創造の失敗の責任はTitanたち自身にあると信じていた。ついに宇宙全体に及ぶ彼らの業を覆すことを決めた彼は、物理宇宙を炎に包む止めようのない軍勢を築くと決意した。", "." },
})
